package com.cooled.core.protocol

/**
 * Port of the digit/colon bitmap-table dispatch inside
 * CoolledUXUtils.getDataWithTimeCountCombineProgram(DeviceManager.CoolleduxTimeCountProgramContent)
 * (reverse/jadx/sources/com/jtkj/led1248/light/utils/CoolledUXUtils.java, ~line 4056-4306).
 *
 * jadx's `-m simple` pseudocode for this function has the same kind of scrambled
 * control flow documented elsewhere in this file (see docs/APK_REVERSE_ENGINEERING_NOTES.md):
 * naively reading it suggests a genuine backward loop between the row-24 and
 * row-20/row-32 dispatch blocks (an artifact of jadx re-using `L40`/`L45`/`L59`
 * labels for unrelated basic blocks), which a literal transcription would have
 * gotten wrong. This was cross-checked and rebuilt directly from
 * `reverse/apktool/smali_classes3/com/jtkj/led1248/light/utils/CoolledUXUtils.smali`
 * (method at smali line 16326), which has no backward branches at all here - it's
 * a clean linear sequence of `sget DEVICE_ROW/DEVICE_COLUMN` comparisons
 * (`:cond_1`..`:cond_11` for `timeCountMode == 0`, an identical `:cond_13`..`:cond_23`
 * sequence for `timeCountMode == 1`), each either overwriting a "digit table" /
 * "colon table" register pair or falling through to the next comparison.
 *
 * Findings from that trace (all confirmed against the raw registers, not
 * inferred from jadx's rendering):
 *
 * 1. **`timeCountMode == 0` and `timeCountMode == 1` resolve to byte-identical
 *    digit/colon tables for every device size.** The two chains reference the
 *    exact same constant-pool string literals (verified by hashing every
 *    literal in file order: the `timeCountMode==1` chain's 23 literals are a
 *    perfect duplicate, in the same order, of the `timeCountMode==0` chain's
 *    23 literals) and apply them under identical row/column comparisons. This
 *    looks like the same dispatch logic duplicated once per mode rather than
 *    two independently-authored tables. [resolve] below implements this
 *    dispatch once and reuses it for both modes.
 * 2. **Any other `timeCountMode` value produces an empty digit table AND an
 *    empty colon table** (the `v11`/`v3` smali registers are never written -
 *    both stay at their initial `""`). The APK's own `getSplitDataStringByDot("")`
 *    / `getHexDataStringByDot(...)` then calls `Integer.valueOf("".trim())`,
 *    which throws `NumberFormatException` - i.e. the real APK would crash on
 *    this input too. This port intentionally does not special-case it; letting
 *    `CommaSeparatedByteTable.parse("")` throw the same way is the faithful
 *    behavior (presumably unreachable in practice - the APK's own UI likely
 *    never offers a `timeCountMode` other than 0/1).
 * 3. **`DEVICE_ROW == 16` never reaches its own elaborate per-column table.**
 *    The row-16-specific dispatch (columns 32/64/144/192) computes real
 *    per-size tables into a `v9`/`v10` register pair, but the *only* place
 *    that later reads those registers is the row-24-and-column-under-96
 *    fallback (`v6 <- v9; v4 <- v10`) - which requires `DEVICE_ROW == 24`, not
 *    16. For an actual 16-row device the computed `v9`/`v10` are simply never
 *    consumed; the final digit/colon tables fall through to the plain
 *    top-level defaults ([DEFAULT_DIGIT]/[DEFAULT_COLON]) regardless of
 *    column. Confirmed dead code in the APK, not a bug in this port - not
 *    modeled here (there is nothing to model: it has no observable effect).
 * 4. A `DEVICE_ROW == 24 && DEVICE_COLUMN < 96` device (not matching the 48/64
 *    special cases either) resolves to *empty* tables too, inheriting the same
 *    never-written `v9`/`v10` registers as note 3 - which, for a device that
 *    also isn't row-16, are simply untouched empty strings. This would also
 *    throw via `CommaSeparatedByteTable.parse("")`, matching the APK.
 *
 * The digit-table literals (`DIGIT_*`) and colon-table literals (`COLON_*`)
 * below are extracted verbatim from the Java source (mechanically, via a
 * script matching on content hash - not hand-retyped), per the guidance in
 * `CommaSeparatedByteTable`'s own doc comment: a single mistyped byte in a
 * table this dense would silently corrupt one glyph's shape on the real LED
 * matrix, which neither a smali cross-check nor a unit test derived from the
 * same (possibly mistranscribed) source would catch.
 */
internal object TimeCountDigitTables {
    /**
     * Resolves the (digitTableCsv, colonTableCsv) pair for a given device size
     * and `timeCountMode`. Returns the raw comma-separated-decimal strings
     * (matching the APK's own literal shape); parse with
     * [CommaSeparatedByteTable.parse].
     */
    fun resolve(deviceRow: Int, deviceColumn: Int, timeCountMode: Int): Pair<String, String> {
        if (timeCountMode != 0 && timeCountMode != 1) return "" to ""

        // Row-24 dispatch (smali :cond_6..:cond_a): resolves (digit=v4, colon=v6).
        var digit = DEFAULT_DIGIT
        var colon = DEFAULT_COLON
        if (deviceRow == 24) {
            when {
                deviceColumn == 48 -> digit = DIGIT_24x48
                deviceColumn == 64 -> {
                    colon = COLON_20x64_24x64
                    digit = DIGIT_611_20x64_24x64
                }
                deviceColumn == 144 -> colon = COLON_24x144
                deviceColumn >= 96 -> {
                    digit = DIGIT_24_WIDE_FALLBACK
                    colon = COLON_24_WIDE_FALLBACK
                }
                else -> {
                    // deviceColumn < 96: :cond_a's v6<-v9/v4<-v10 fallback - both
                    // registers are untouched empty strings for row 24 (see note 4).
                    digit = ""
                    colon = ""
                }
            }
        }

        // Row-20 dispatch (smali :cond_b/:cond_c): row20+col64 sets the digit
        // table *and* the colon table directly; anything else falls back to
        // the row-24-derived (or default) digit table computed above.
        val afterRow20Digit: String
        if (deviceRow == 20 && deviceColumn == 64) {
            afterRow20Digit = DIGIT_611_20x64_24x64
            colon = COLON_20x64_24x64
        } else {
            afterRow20Digit = digit
        }

        // Row-32 dispatch (smali :cond_d..:cond_11): sets both registers
        // directly per column; the fallback (row != 32, or row 32 with an
        // unmatched column < 192) keeps the digit table from the row-20/24
        // stage and the colon table from the row-24/20 stage.
        return when {
            deviceRow == 32 && deviceColumn == 64 -> DIGIT_32x64 to COLON_32x64
            deviceRow == 32 && deviceColumn == 96 -> DIGIT_32x96 to COLON_32x96
            deviceRow == 32 && deviceColumn == 128 -> DIGIT_32x128 to COLON_32x128
            deviceRow == 32 && deviceColumn == 160 -> DIGIT_32x160 to COLON_32x160
            deviceRow == 32 && deviceColumn >= 192 -> DIGIT_32x192plus to COLON_32x192plus
            else -> afterRow20Digit to colon
        }
    }

